/bin/sh -lc "node --input-type=module <<'JS'
import { chromium } from '@playwright/test';
import { serveArtifact } from './tests/artifact-server.ts';
const server = await serveArtifact();
const browser = await chromium.launch({ headless: true });
try {
  const page = await browser.newPage({ viewport: { width: 360, height: 800 } });
  await page.goto(server.url);
  await page.getByRole('button', { name: 'Tournament', exact: true }).click();
  await page.getByLabel('Players', { exact: true }).selectOption('8');
  for (const [index, name] of ['Ada', 'Bo', 'Cy', 'Dee', 'Eli', 'Flo', 'Gia', 'Hal'].entries())
    await page.getByLabel("'`Player ${index + 1}`, { exact: true }).fill(name);
  await page.screenshot({ path: '"'test-results/tournament-setup-phone.png', fullPage: true });
  await page.getByRole('button', { name: 'Start tournament', exact: true }).click();
  await page.screenshot({ path: 'test-results/tournament-bracket-phone.png', fullPage: true });
  console.log(JSON.stringify({ pageWidth: await page.evaluate(() => document.documentElement.scrollWidth), viewportWidth: 360, matches: await page.getByRole('article').count() }));
} finally {
  await browser.close();
  await server.close();
}
JS"

